-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or
-- after it half to even (a correction by the date of the claim it corrects). Null means the sheet's
-- today. Settled and stated figures keep what they were fixed at.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- A claim's number: when a claim is opened it takes the sheet's next number (1, 2, ...), with no
-- gaps and never reused. A DRAFT claim has none, and voiding a claim clears it. The sheet keeps the
-- last number it gave out; opening a claim takes the sheet row's lock to bump it.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
-- A period on a sheet: a name, unique on the sheet ignoring case and surrounding spaces (name_key is
-- the trimmed name lower-cased), and a from and to date, both inclusive. No two periods on a sheet
-- overlap (kept by the app). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every
-- full 30 days it is overdue. Never bound by a statement; frozen in when the claim is settled.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL;
